ALTER TABLE "Transaction" ADD CONSTRAINT transaction_money CHECK (amount > 0 AND "reportingAmount" >= 0 AND "reportingRate" > 0), ADD CONSTRAINT transaction_direction CHECK (type IN ('INCOME','EXPENSE') AND (NOT "isSadaqah" OR type='EXPENSE')), ADD CONSTRAINT transaction_currency CHECK (currency ~ '^[A-Z]{3}$' AND "reportingCurrency" ~ '^[A-Z]{3}$'), ADD CONSTRAINT transaction_version CHECK (version>0);
ALTER TABLE "Asset" ADD CONSTRAINT asset_value CHECK (("valuationMode"='MANUAL' AND "declaredValue" IS NOT NULL AND "declaredValue">0 AND "weightGrams" IS NULL AND purity IS NULL) OR ("valuationMode"='METAL_RATE' AND type IN ('GOLD','SILVER') AND "declaredValue" IS NULL AND "weightGrams" IS NOT NULL AND purity IS NOT NULL AND "weightGrams">0 AND purity>0 AND purity<=1)), ADD CONSTRAINT asset_currency CHECK (currency ~ '^[A-Z]{3}$'), ADD CONSTRAINT asset_version CHECK (version>0);
ALTER TABLE "Debt" ADD CONSTRAINT debt_value CHECK ("originalAmount">0 AND "remainingAmount">=0 AND "remainingAmount"<="originalAmount"), ADD CONSTRAINT debt_direction CHECK (direction IN ('I_OWE','OWED_TO_ME')), ADD CONSTRAINT debt_status CHECK ((status='SETTLED' AND "remainingAmount"=0 AND "settledAt" IS NOT NULL) OR (status='OPEN' AND "remainingAmount">0 AND "settledAt" IS NULL)), ADD CONSTRAINT debt_date CHECK ("dueOn" IS NULL OR "dueOn">="openedOn"), ADD CONSTRAINT debt_currency CHECK (currency ~ '^[A-Z]{3}$');
ALTER TABLE "DebtEvent" ADD CONSTRAINT debt_event_value CHECK ("previousRemaining">=0 AND "nextRemaining">=0);
ALTER TABLE "ZakatPaymentRecord" ADD CONSTRAINT payment_positive CHECK (amount>0), ADD CONSTRAINT payment_currency CHECK (currency ~ '^[A-Z]{3}$');
ALTER TABLE "ZakatYear" ADD CONSTRAINT year_positive CHECK ("assessedAmount">=0), ADD CONSTRAINT year_currency CHECK (currency ~ '^[A-Z]{3}$');
ALTER TABLE "ZakatPolicyVersion" ADD CONSTRAINT policy_values CHECK ("goldGrams">0 AND "silverGrams">0 AND "annualRate">0 AND "annualRate"<=1 AND status IN ('DRAFT','APPROVED') AND (status<>'APPROVED' OR ("reviewedBy" IS NOT NULL AND "approvedAt" IS NOT NULL)));
ALTER TABLE "MetalPriceSnapshot" ADD CONSTRAINT metal_positive CHECK ("usdPerTroyOz">0 AND metal IN ('XAU','XAG'));
ALTER TABLE "ExchangeRateSnapshot" ADD CONSTRAINT fx_positive CHECK ("perUsd">0 AND currency ~ '^[A-Z]{3}$');
ALTER TABLE "QuranBookmark" ADD CONSTRAINT bookmark_range CHECK (surah BETWEEN 1 AND 114 AND ayah BETWEEN 1 AND 286);
ALTER TABLE "QuranReadingPosition" ADD CONSTRAINT progress_range CHECK (surah BETWEEN 1 AND 114 AND ayah BETWEEN 1 AND 286);
ALTER TABLE "UserPreference" ADD CONSTRAINT preference_currency CHECK (currency IN ('BDT','USD','EUR','GBP','SAR','AED','INR','MYR','CAD','AUD')), ADD CONSTRAINT preference_school CHECK (school IN (0,1));
CREATE FUNCTION prevent_closed_year_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Historical assessment is immutable; create an explicit new revision in a reviewed migration.'; END; $$;
CREATE TRIGGER immutable_zakat_year BEFORE UPDATE ON "ZakatYear" FOR EACH ROW EXECUTE FUNCTION prevent_closed_year_update();
CREATE FUNCTION prevent_approved_policy_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='APPROVED' THEN RAISE EXCEPTION 'Approved policy is immutable; create a new version.'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER immutable_approved_policy BEFORE UPDATE OR DELETE ON "ZakatPolicyVersion" FOR EACH ROW EXECUTE FUNCTION prevent_approved_policy_change();
